import { Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: An error has occurred. Use this interaction for a stand-alone error; errors can also be sent as part of other interaction payloads.
*/
export type ErrorInteraction = {
    events: Array<ErrorEvent | Identity | PartyIdentification>;
}

export class ErrorInteractionBuilder {

    private errorInteraction: ErrorInteraction = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withErrorEvent(errorEvent: ErrorEvent) : ErrorInteractionBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ErrorInteractionBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ErrorInteractionBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ErrorInteraction {
        if(this.errorEvent) {
            this.errorInteraction.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.errorInteraction.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.errorInteraction.events.push(this.partyIdentification);
        }

        return this.errorInteraction;
    }
}
